static inline void
vk_queue_lock(struct vk_bundle_queue *q)
{
	assert(q != NULL);
	os_mutex_lock(&q->mutex);
}

static inline int
vk_queue_trylock(struct vk_bundle_queue *q)
{
	assert(q != NULL);
	return os_mutex_trylock(&q->mutex);
}

static inline void
vk_queue_unlock(struct vk_bundle_queue *q)
{
	assert(q != NULL);
	os_mutex_unlock(&q->mutex);
}

